//! Deferred historical receipt indexing; no new observations or application attempt.
async fn historical_receipt(c:&mut PgConnection,req:&str,valid:bool)->Value{
 let value=if valid{json!({"requisition":req,"confirmation_source":"naukri_application_status_ui","operation_mode":"owner_authorized_software_operated_ui","status":"Application Sent","persistent_after_reload":true,"private_evidence_sha256":"a".repeat(64),"observed_at":"2026-01-01T00:00:00Z","job_title":"Fictional historical engineer","hiring_company":"Fictional historical employer"})}else{json!({"damaged":true})};browser_save(c,&format!("naukri_receipt:{req}"),value.clone()).await;value
}
#[tokio::test(flavor="current_thread")]
#[ignore="requires dedicated disposable PostgreSQL harness"]
async fn retained_receipt_index_uses_five_row_cursor_and_never_rewrites_original_evidence(){
 let mut c=browser_fixture().await;for i in 0..7{historical_receipt(&mut c,&format!("1234567890{i:02}"),i!=2).await;}sqlx::query("UPDATE owner_preferences SET updated_at='2026-11-16T00:00:00Z' WHERE starts_with(key,'naukri_receipt:')").execute(&mut c).await.unwrap();let original:Value=sqlx::query_scalar("SELECT jsonb_object_agg(key,value) FROM owner_preferences WHERE starts_with(key,'naukri_receipt:')").fetch_one(&mut c).await.unwrap();assert_eq!(automated_apply_agents::execution::retained_index::tick(&mut c).await.unwrap(),4);assert_eq!(browser_pref(&mut c,"apply_history_cursor").await["key"],"naukri_receipt:123456789004");assert_eq!(automated_apply_agents::execution::retained_index::tick(&mut c).await.unwrap(),2);assert_eq!(automated_apply_agents::execution::retained_index::tick(&mut c).await.unwrap(),0);let works:Vec<Value>=sqlx::query_scalar("SELECT value FROM owner_preferences WHERE starts_with(key,'apply_work:')").fetch_all(&mut c).await.unwrap();assert_eq!(works.len(),6);for work in works{assert_eq!(work["stage"],"SUBMITTED_RECORDED");assert_eq!(work["submission_mode"],"owner_authorized_software_operated_ui");assert_eq!(work["admitted_actions"],json!([]));assert!(work["packet_id"].is_null());assert!(work["lease_token"].is_null());}assert_eq!(sqlx::query_scalar::<_,Value>("SELECT jsonb_object_agg(key,value) FROM owner_preferences WHERE starts_with(key,'naukri_receipt:')").fetch_one(&mut c).await.unwrap(),original);assert_eq!(sqlx::query_scalar::<_,i64>("SELECT count(*) FROM owner_preferences WHERE starts_with(key,'naukri_worker_receipt:') OR starts_with(key,'apply_budget:')").fetch_one(&mut c).await.unwrap(),0);
}
#[tokio::test(flavor="current_thread")]
#[ignore="requires dedicated disposable PostgreSQL harness"]
async fn retained_receipt_index_preserves_strict_worker_unknown_and_active_form_records_unchanged(){
 let mut c=browser_fixture().await;execution_running(&mut c).await;let mut before=Vec::new();for(index,stage)in ["SUBMITTED_CONFIRMED","SUBMISSION_UNKNOWN","QUESTIONS"].iter().enumerate(){let req=format!("1234567890{index:02}");let mut work=execution_enqueue(&mut c,&req).await;work["stage"]=json!(stage);work["status"]=json!(if index==0{"complete"}else if index==1{"unknown"}else{"executing"});work["admitted_actions"]=json!([{"fingerprint":"apply:retained"}]);if index==2{work["form_pending"]=json!(true);work["packet_id"]=json!(Uuid::new_v4());}let key=format!("apply_work:{}",work["id"].as_str().unwrap());browser_save(&mut c,&key,work.clone()).await;before.push((key,work));historical_receipt(&mut c,&req,true).await;}assert_eq!(automated_apply_agents::execution::retained_index::tick(&mut c).await.unwrap(),0);for(key,work)in before{assert_eq!(browser_pref(&mut c,&key).await,work);}assert!(browser_pref(&mut c,"apply_history_cursor").await["key"].as_str().is_some());
}
#[tokio::test(flavor="current_thread")]
#[ignore="requires dedicated disposable PostgreSQL harness"]
async fn retained_receipt_index_event_ack_failure_rolls_back_work_and_cursor(){
 let mut c=browser_fixture().await;historical_receipt(&mut c,"123456789012",true).await;let before=browser_snapshot(&mut c).await;sqlx::raw_sql("CREATE FUNCTION fixture_retained_event_drop() RETURNS trigger LANGUAGE plpgsql AS $$ BEGIN IF starts_with(NEW.key,'apply_event:') THEN RETURN NULL; END IF; RETURN NEW; END $$;CREATE TRIGGER fixture_retained_event_drop BEFORE INSERT ON owner_preferences FOR EACH ROW EXECUTE FUNCTION fixture_retained_event_drop()").execute(&mut c).await.unwrap();assert_eq!(automated_apply_agents::execution::retained_index::tick(&mut c).await.unwrap_err(),Failure("execution_write_ack_failed"));assert_eq!(browser_snapshot(&mut c).await,before);sqlx::raw_sql("DROP TRIGGER fixture_retained_event_drop ON owner_preferences;DROP FUNCTION fixture_retained_event_drop()").execute(&mut c).await.unwrap();
}
#[tokio::test(flavor="current_thread")]
#[ignore="requires dedicated disposable PostgreSQL harness"]
async fn retained_receipt_index_idle_never_waits_on_owner_lock_and_historical_projection_cannot_enable_automatic(){
 let mut c=browser_fixture().await;browser_save(&mut c,"agent_conversation:primary",json!({"retain":true})).await;let mut owner=connection().await;let mut tx=owner.begin().await.unwrap();sqlx::query("SELECT key FROM owner_preferences WHERE key='agent_conversation:primary' FOR UPDATE").execute(&mut *tx).await.unwrap();sqlx::query("SET lock_timeout='100ms'").execute(&mut c).await.unwrap();assert_eq!(automated_apply_agents::execution::retained_index::tick(&mut c).await.unwrap(),0);tx.rollback().await.unwrap();drop(c);
 let(mut c,_binding,_profile)=sync_fixture(json!([])).await;historical_receipt(&mut c,"123456789012",true).await;assert_eq!(automated_apply_agents::execution::retained_index::tick(&mut c).await.unwrap(),1);let config=browser_pref(&mut c,"application_queue_policy").await;let mut policy=config["policy"].clone();policy["platforms"]["naukri"]["mode"]=json!("AUTOMATIC");let before=browser_snapshot(&mut c).await;assert_eq!(execution_mutate(&mut c,automated_apply_agents::execution::Route::Policy,json!({"expected_revision":config["revision"],"policy":policy})).await.unwrap_err(),Failure("automatic_first_verified_worker_receipt_required"));assert_eq!(browser_snapshot(&mut c).await,before);
}
